#pragma once
#include <cstdint>
namespace ks{
class SquareRootTask final{public:enum class Stage{Retain,Clear,SetTrial,AddTrial,CaptureCandidate,Square,Compare,Admit,Reject,HalfTrial,AdmitMore,Restore,Finish,Complete};Stage stage()const{return stage_;}uint8_t result()const{return result_;}uint8_t trial()const{return trial_;}uint16_t square()const{return square_;}uint16_t target()const{return target_;}unsigned nextClocks()const{switch(stage_){case Stage::Retain:case Stage::Restore:return 11;case Stage::Square:return 15;case Stage::Finish:return 17;case Stage::Complete:return 0;default:return 3;}}
 template<class Reader>unsigned advanceBefore(unsigned available,Reader&&read){unsigned used=0;while(auto cost=nextClocks()){if(cost>available-used)break;switch(stage_){case Stage::Retain:stage_=Stage::Clear;break;case Stage::Clear:result_=0;stage_=Stage::SetTrial;break;case Stage::SetTrial:trial_=128;stage_=Stage::AddTrial;break;case Stage::AddTrial:result_=uint8_t(result_+trial_);stage_=Stage::CaptureCandidate;break;case Stage::CaptureCandidate:stage_=Stage::Square;break;case Stage::Square:square_=unsigned(result_)*result_;stage_=Stage::Compare;break;case Stage::Compare:target_=uint16_t(read());stage_=Stage::Admit;break;case Stage::Admit:stage_=square_<=target_?Stage::HalfTrial:Stage::Reject;break;case Stage::Reject:result_=uint8_t(result_-trial_);stage_=Stage::HalfTrial;break;case Stage::HalfTrial:trial_>>=1;stage_=Stage::AdmitMore;break;case Stage::AdmitMore:stage_=trial_?Stage::AddTrial:Stage::Restore;break;case Stage::Restore:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}
private:Stage stage_=Stage::Retain;uint8_t result_=0,trial_=0;uint16_t square_=0,target_=0;
};}
